function chart(rows,series,options={}){
 if(!rows.length)return '<div class="empty">Sem valores para este período.</div>';
 const W=window.innerWidth<720?480:720,H=options.height||270,L=57,RR=16,T=20,B=35,w=W-L-RR,h=H-T-B,maxT=Math.max(1,rows.at(-1).t),vals=rows.flatMap(r=>series.map(s=>Number(r[s.key])||0)),lo=Math.min(0,...vals),hi=Math.max(1,...vals),span=hi-lo,raw=span/4,mag=10**Math.floor(Math.log10(raw)),step=Math.ceil(raw/mag)*mag,ylo=Math.floor(lo/step)*step,yhi=Math.ceil(hi/step)*step;
 const x=t=>L+t/maxT*w,y=v=>T+(yhi-v)/(yhi-ylo)*h;
 let grid='';for(let v=ylo;v<=yhi+step/100;v+=step){grid+='<line class="'+(v===0?'zero':'grid')+'" x1="'+L+'" x2="'+(W-RR)+'" y1="'+y(v)+'" y2="'+y(v)+'"/><text x="'+(L-10)+'" y="'+(y(v)+3)+'" text-anchor="end">'+esc(Math.abs(v)>=1e6?fmt(v/1e6,0)+' mi':Math.abs(v)>=1000?fmt(v/1000,0)+' mil':fmt(v,0))+'</text>';}
 for(let i=0;i<=4;i++){const t=Math.round(maxT*i/4);grid+='<text x="'+x(t)+'" y="'+(H-10)+'" text-anchor="middle">M'+t+'</text>';}
 let exposure='';if(options.exposure&&series.length>=2){
  const a=options.exposure.availableKey,b=options.exposure.workKey,fill=options.exposure.fill||'#c9826e';
  function poly(points){return '<polygon points="'+points.map(pt=>pt[0].toFixed(2)+','+pt[1].toFixed(2)).join(' ')+'" fill="'+fill+'" fill-opacity=".12"/>';}
  for(let i=0;i<rows.length-1;i++){
   const r0=rows[i],r1=rows[i+1],a0=Number(r0[a])||0,a1=Number(r1[a])||0,b0=Number(r0[b])||0,b1=Number(r1[b])||0,d0=b0-a0,d1=b1-a1,x0=x(r0.t),x1=x(r1.t);
   if(d0>0&&d1>0)exposure+=poly([[x0,y(a0)],[x1,y(a1)],[x1,y(b1)],[x0,y(b0)]]);
   else if(d0>0&&d1<=0){const q=d0/(d0-d1),xc=x0+(x1-x0)*q,vc=a0+(a1-a0)*q;exposure+=poly([[x0,y(a0)],[xc,y(vc)],[x0,y(b0)]]);}
   else if(d0<=0&&d1>0){const q=(-d0)/(d1-d0),xc=x0+(x1-x0)*q,vc=a0+(a1-a0)*q;exposure+=poly([[xc,y(vc)],[x1,y(a1)],[x1,y(b1)]]);}
  }
 }
 let lines='';for(const [j,s] of series.entries()){const path=rows.map((r,i)=>(i?'L':'M')+x(r.t).toFixed(2)+','+y(r[s.key]||0).toFixed(2)).join(' ');if(j===0&&options.fill!==false&&!options.exposure)lines+='<path d="'+path+' L'+x(rows.at(-1).t)+','+y(0)+' L'+x(rows[0].t)+','+y(0)+'Z" fill="'+colors[s.color]+'" fill-opacity=".055"/>';lines+='<path d="'+path+'" fill="none" stroke="'+colors[s.color]+'" stroke-width="2.2" stroke-linejoin="round"/>';}
 const marker=options.marker;let mark='';if(marker!==undefined&&marker<=maxT){const xx=x(marker);mark='<line x1="'+xx+'" x2="'+xx+'" y1="'+T+'" y2="'+(H-B)+'" stroke="#98a88f" stroke-dasharray="3 4"/><text x="'+Math.min(xx+5,W-102)+'" y="12">Entrega · M'+marker+'</text>';}
 let exposureMark='';if(options.exposure&&Number.isFinite(options.exposure.peakMonth)&&options.exposure.peakMonth<=maxT){
  const pr=rows.find(r=>r.t===options.exposure.peakMonth);if(pr){const av=Number(pr[options.exposure.availableKey])||0,wv=Number(pr[options.exposure.workKey])||0,xx=x(pr.t),ya=y(av),yw=y(wv),ym=(ya+yw)/2,label=money(options.exposure.peakValue,false),boxW=Math.min(148,Math.max(94,label.length*6.4+18)),bx=Math.max(L+4,Math.min(W-RR-boxW-4,xx+10)),by=Math.max(T+5,Math.min(H-B-34,ym-16));exposureMark='<line class="exposure-guide" x1="'+xx+'" x2="'+xx+'" y1="'+yw+'" y2="'+ya+'"/><circle class="exposure-dot" cx="'+xx+'" cy="'+ym+'" r="3.5"/><g class="exposure-label"><rect x="'+bx+'" y="'+by+'" width="'+boxW+'" height="32" rx="5"/><text x="'+(bx+9)+'" y="'+(by+12)+'">PICO DE EXPOSIÇÃO</text><text class="value" x="'+(bx+9)+'" y="'+(by+25)+'">'+esc(label)+'</text></g>';}}
 const hover=rows.map(r=>'<rect x="'+Math.max(L,x(r.t)-w/maxT/2)+'" y="'+T+'" width="'+Math.max(2,w/maxT)+'" height="'+h+'" fill="transparent"><title>M'+r.t+' — '+series.map(s=>s.label+': '+money(r[s.key],false)).join(' | ')+(options.exposure?' | Exposição: '+money(Math.max(0,(Number(r[options.exposure.workKey])||0)-(Number(r[options.exposure.availableKey])||0)),false):'')+'</title></rect>').join('');
 const extraLegend=options.exposure?'<span class="legend-exposure"><i></i>Exposição de caixa · pico '+money(options.exposure.peakValue)+'</span>':'';
 return '<div class="legend">'+series.map(s=>'<span><i style="background:'+colors[s.color]+'"></i>'+s.label+'</span>').join('')+extraLegend+'</div><svg class="chart" viewBox="0 0 '+W+' '+H+'" role="img" aria-label="'+esc(options.title||series.map(s=>s.label).join(' versus '))+'"><title>'+esc(options.title||'Valores nominais por mês')+'</title>'+grid+exposure+lines+mark+exposureMark+hover+'</svg>';
}
