function normalizedManualWeights(){
 const values=(p.workWeights||[]).map(Number);const sum=values.reduce((a,b)=>a+(Number.isFinite(b)&&b>0?b:0),0);
 if(values.length!==p.duration||sum<=0)return E.weights({...p,curve:'s'}).map(v=>v*100);
 return values.map(v=>Math.max(0,v)/sum*100);
}
function redistributeManualWeight(index,target){
 const values=normalizedManualWeights(),n=values.length;if(!n)return;
 if(n===1){p.workWeights=[100];return;}
 target=Math.max(0,Math.min(95,target));const current=values[index],others=100-current;
 if(others<=0.000001){const each=(100-target)/(n-1);for(let i=0;i<n;i++)values[i]=i===index?target:each;}
 else{const factor=(100-target)/others;for(let i=0;i<n;i++)values[i]=i===index?target:values[i]*factor;}
 p.workWeights=values.map(v=>Number(v.toFixed(6)));
}
function curveEditor(){
 const values=R.workWeights.map(v=>v*100),n=values.length,W=Math.max(840,n*34+150),H=326,L=52,RR=98,T=28,B=45,w=W-L-RR,h=H-T-B,maxWeight=Math.min(100,Math.max(20,Math.ceil((Math.max(...values,1)*1.35)/5)*5));
 const x=i=>L+(n===1?w/2:i/(n-1)*w),y=v=>T+(maxWeight-v)/maxWeight*h;
 // Mesma série da Visão Executiva: disponibilidade líquida acumulada da carteira.
 const rec=Array.from({length:n},(_,i)=>R.rows[p.workStart+i]?.cumAvailable||0),minRec=Math.min(0,...rec),maxRec=Math.max(1,...rec),recSpan=Math.max(1,maxRec-minRec),yr=v=>T+(maxRec-v)/recSpan*h;
 const path=values.map((v,i)=>(i?'L':'M')+x(i).toFixed(1)+','+y(v).toFixed(1)).join(' ');
 const area=path+' L'+x(n-1).toFixed(1)+','+(T+h)+' L'+x(0).toFixed(1)+','+(T+h)+' Z';
 const recPath=rec.map((v,i)=>(i?'L':'M')+x(i).toFixed(1)+','+yr(v).toFixed(1)).join(' ');
 let grid='';for(let j=0;j<=4;j++){const v=maxWeight*j/4,yy=y(v);grid+='<line class="curve-grid" x1="'+L+'" x2="'+(W-RR)+'" y1="'+yy+'" y2="'+yy+'"/><text class="curve-axis" x="'+(L-9)+'" y="'+(yy+3)+'" text-anchor="end">'+fmt(v,0)+'%</text>';}
 const step=Math.max(1,Math.ceil(n/10));for(let i=0;i<n;i+=step)grid+='<text class="curve-axis" x="'+x(i)+'" y="'+(H-12)+'" text-anchor="middle">M'+(p.workStart+i)+'</text>';
 grid+='<text class="curve-axis right" x="'+(W-RR+10)+'" y="'+(T+3)+'">'+money(maxRec)+'</text><text class="curve-axis right" x="'+(W-RR+10)+'" y="'+(T+h/2+3)+'">'+money((maxRec+minRec)/2)+'</text><text class="curve-axis right" x="'+(W-RR+10)+'" y="'+(T+h+3)+'">'+money(minRec)+'</text>';
 const points=values.map((v,i)=>'<g class="curve-point-group"><circle class="curve-point" data-curve-point="'+i+'" cx="'+x(i)+'" cy="'+y(v)+'" r="7"><title>M'+(p.workStart+i)+' · '+fmt(v,2)+'% da obra</title></circle><text class="curve-point-value" data-curve-value="'+i+'" x="'+x(i)+'" y="'+(y(v)-12)+'" text-anchor="middle">'+fmt(v,1)+'%</text></g>').join('');
 return '<div class="curve-editor"><div class="curve-tools"><div class="curve-legend"><span><i class="work"></i>Distribuição física da obra</span><span class="'+(receivablesVisible?'':'muted')+'"><i class="receivable"></i>Carteira líquida acumulada</span></div>'+btn('toggle-receivables',receivablesVisible?'Ocultar carteira':'Mostrar carteira',receivablesVisible?'x':'chart','small')+'</div><div class="curve-scroll"><svg class="curve-editor-svg" data-curve-editor viewBox="0 0 '+W+' '+H+'" data-top="'+T+'" data-height="'+h+'" data-max-weight="'+maxWeight+'" style="width:'+W+'px;min-width:100%" role="img" aria-label="Editor gráfico da distribuição física da obra com carteira líquida acumulada"><path class="curve-area" data-curve-area d="'+area+'"/>'+grid+(receivablesVisible?'<path class="curve-receivables" d="'+recPath+'"/>':'')+'<path class="curve-work" data-curve-path d="'+path+'"/>'+points+'</svg></div><div class="curve-instructions">'+ico('sliders')+'<div><strong>Arraste os pontos verdes para cima ou para baixo.</strong><p>A soma permanece em 100%: ao alterar um mês, os demais são redistribuídos proporcionalmente. A curva pontilhada agora é exatamente a <b>carteira líquida acumulada</b> usada na Visão Executiva, recortada ao período da obra e lida na escala em R$ à direita.</p></div></div></div>';
}
function repaintCurveEditor(){
 const svg=document.querySelector('[data-curve-editor]');if(!svg)return;const values=normalizedManualWeights(),n=values.length,box=svg.viewBox.baseVal,L=52,RR=88,T=Number(svg.dataset.top),h=Number(svg.dataset.height),W=box.width,maxWeight=Number(svg.dataset.maxWeight),w=W-L-RR;
 const x=i=>L+(n===1?w/2:i/(n-1)*w),y=v=>T+(maxWeight-v)/maxWeight*h;
 const path=values.map((v,i)=>(i?'L':'M')+x(i).toFixed(1)+','+y(v).toFixed(1)).join(' ');
 const area=path+' L'+x(n-1).toFixed(1)+','+(T+h)+' L'+x(0).toFixed(1)+','+(T+h)+' Z';
 svg.querySelector('[data-curve-path]').setAttribute('d',path);svg.querySelector('[data-curve-area]').setAttribute('d',area);
 values.forEach((v,i)=>{const pt=svg.querySelector('[data-curve-point="'+i+'"]'),label=svg.querySelector('[data-curve-value="'+i+'"]');if(pt){pt.setAttribute('cy',y(v));pt.querySelector('title').textContent='M'+(p.workStart+i)+' · '+fmt(v,2)+'% da obra';}if(label){label.setAttribute('y',y(v)-12);label.textContent=fmt(v,1)+'%';}});
}
function updateCurveDrag(event){
 if(!dragState)return;const svg=dragState.svg,rect=svg.getBoundingClientRect(),T=Number(svg.dataset.top),h=Number(svg.dataset.height),maxWeight=Number(svg.dataset.maxWeight),svgY=(event.clientY-rect.top)/rect.height*svg.viewBox.baseVal.height,target=maxWeight*(1-(svgY-T)/h);
 redistributeManualWeight(dragState.index,target);calculate(false);repaintCurveEditor();
}

function planDate(params,t){const [y,m]=params.start.split('-').map(Number);return new Date(Date.UTC(y,m-1+t,1)).toLocaleDateString('pt-BR',{month:'short',year:'2-digit',timeZone:'UTC'}).replace('.','');}
function paceChart(rows,planKey,actualKey,options={}){
 if(!rows.length)return '<div class="empty">Sem dados para comparar.</div>';
 const W=window.innerWidth<720?480:720,H=250,L=50,RR=18,T=22,B=34,w=W-L-RR,h=H-T-B,maxT=Math.max(1,rows.at(-1).t),vals=rows.flatMap(r=>[Number(r[planKey])||0,Number.isFinite(r[actualKey])?Number(r[actualKey]):null]).filter(v=>v!==null),max=Math.max(options.max||0,1,...vals),step=Math.max(1,Math.ceil(max/4/(options.unit==='percent'?5:1))*(options.unit==='percent'?5:1)),ymax=Math.ceil(max/step)*step;
 const x=t=>L+t/maxT*w,y=v=>T+(ymax-v)/ymax*h,format=v=>options.unit==='percent'?pct(v,0):fmt(v,0);
 let grid='';for(let v=0;v<=ymax+.001;v+=step)grid+='<line class="grid" x1="'+L+'" x2="'+(W-RR)+'" y1="'+y(v)+'" y2="'+y(v)+'"/><text x="'+(L-9)+'" y="'+(y(v)+3)+'" text-anchor="end">'+format(v)+'</text>';for(let i=0;i<=4;i++){const t=Math.round(maxT*i/4);grid+='<text x="'+x(t)+'" y="'+(H-9)+'" text-anchor="middle">M'+t+'</text>';}
 const planPath=rows.map((r,i)=>(i?'L':'M')+x(r.t).toFixed(1)+','+y(r[planKey]||0).toFixed(1)).join(' ');
 const actualRows=rows.filter(r=>Number.isFinite(r[actualKey])),actualPath=actualRows.map((r,i)=>(i?'L':'M')+x(r.t).toFixed(1)+','+y(r[actualKey]).toFixed(1)).join(' ');
 const dots=actualRows.map(r=>'<circle cx="'+x(r.t)+'" cy="'+y(r[actualKey])+'" r="3.3" class="pace-dot"><title>M'+r.t+' · realizado '+format(r[actualKey])+'</title></circle>').join('');
 return '<div class="legend"><span><i style="background:'+colors.green+'"></i>Projetado</span><span><i class="actual-line"></i>Realizado</span></div><svg class="chart pace-chart" viewBox="0 0 '+W+' '+H+'" role="img" aria-label="'+esc(options.title||'Projetado versus realizado')+'"><title>'+esc(options.title||'Projetado versus realizado')+'</title>'+grid+'<path d="'+planPath+'" class="pace-plan"/>'+(actualPath?'<path d="'+actualPath+'" class="pace-actual"/>'+dots:'')+'</svg>';
}
function actualComparisonData(){
 current.actuals=normalizeActuals(current.actuals);const a=current.actuals,planParams=a.plan?.params||p;let planR;try{planR=E.simulate(planParams);}catch{planR=R;}
 const salesCutoff=mapLastKey(a.sales),workCutoff=mapLastKey(a.work),lastActual=Math.max(salesCutoff??0,workCutoff??0),limit=actualRange==='all'?Math.max(planR.totals.workEnd,planR.totals.lastSale,lastActual):Math.max(Number(actualRange),lastActual),rows=[];
 let actualSalesCum=0,actualWorkCum=0,planWorkCum=0;
 for(let t=0;t<=limit;t++){
  const salesRecorded=Object.prototype.hasOwnProperty.call(a.sales,t),workRecorded=Object.prototype.hasOwnProperty.call(a.work,t),actualSales=salesRecorded?a.sales[t]:0,actualWork=workRecorded?a.work[t]:0;
  actualSalesCum+=actualSales;actualWorkCum=Math.min(100,actualWorkCum+actualWork);
  const projWork=t>=planParams.workStart&&t<=planR.totals.workEnd?(planR.workWeights[t-planParams.workStart]||0)*100:0;planWorkCum=Math.min(100,planWorkCum+projWork);
  const pr=planR.rows[Math.min(t,planR.rows.length-1)]||{};
  rows.push({t,projSalesMonth:pr.units||0,actualSalesMonth:actualSales,projSalesCum:pr.cumUnits||0,actualSalesCum:salesCutoff!==null&&t<=salesCutoff?actualSalesCum:null,projWorkMonth:projWork,actualWorkMonth:actualWork,projWorkCum:planWorkCum,actualWorkCum:workCutoff!==null&&t<=workCutoff?actualWorkCum:null,salesRecorded,workRecorded});
 }
 const salesWindow=salesCutoff===null?0:Math.max(1,salesCutoff-planParams.salesStart+1),salesActual=salesCutoff===null?0:rows[Math.min(salesCutoff,rows.length-1)].actualSalesCum||0,salesProjected=salesCutoff===null?0:rows[Math.min(salesCutoff,rows.length-1)].projSalesCum||0,salesActualSpeed=salesWindow?salesActual/salesWindow:0,salesProjSpeed=salesWindow?salesProjected/salesWindow:0;
 const workWindow=workCutoff===null?0:Math.max(1,workCutoff-planParams.workStart+1),workActual=workCutoff===null?0:rows[Math.min(workCutoff,rows.length-1)].actualWorkCum||0,workProjected=workCutoff===null?0:rows[Math.min(workCutoff,rows.length-1)].projWorkCum||0,workActualSpeed=workWindow?workActual/workWindow:0,workProjSpeed=workWindow?workProjected/workWindow:0;
 const selloutForecast=salesCutoff!==null&&salesActualSpeed>0?salesCutoff+Math.ceil(Math.max(0,planR.totals.qty-salesActual)/salesActualSpeed):null;
 const workForecast=workCutoff!==null&&workActualSpeed>0?workCutoff+Math.ceil(Math.max(0,100-workActual)/workActualSpeed):null;
 return {a,planParams,planR,rows,salesCutoff,workCutoff,salesActual,salesProjected,salesActualSpeed,salesProjSpeed,workActual,workProjected,workActualSpeed,workProjSpeed,selloutForecast,workForecast};
}
function deltaBadge(v,unit='',inverse=false){if(!Number.isFinite(v))return pill('Sem realizado','sand');const good=inverse?v<=0:v>=0,type=good?'green':'sand',sign=v>0?'+':'';return pill(sign+fmt(v,1)+(unit||''),type);}
function actualsPage(){
 const d=actualComparisonData(),planFixed=!!d.a.plan,comparisonLimit=actualRange==='all'?d.rows.at(-1).t:Math.max(Number(actualRange),d.salesCutoff??0,d.workCutoff??0),salesRows=d.rows.filter(r=>r.t<=comparisonLimit),workRows=d.rows.filter(r=>r.t<=comparisonLimit),maxEdit=actualRange==='all'?Math.max(d.planR.totals.workEnd,d.planR.totals.lastSale,d.salesCutoff??0,d.workCutoff??0):Number(actualRange);
 const baseline='<div class="baseline-card"><div><span class="project-kicker">CENÁRIO PROJETADO DE REFERÊNCIA</span><h3>'+(planFixed?'Baseline congelado':'Premissas atuais · dinâmicas')+'</h3><p>'+(planFixed?'Fixado em '+new Date(d.a.plan.savedAt).toLocaleString('pt-BR')+'. Alterações posteriores nas premissas não mudam esta referência.':'Ainda não há um baseline congelado. Enquanto isso, o realizado é comparado às premissas atuais, que podem mudar.')+'</p></div>'+btn('freeze-plan',planFixed?'Atualizar baseline projetado':'Fixar cenário projetado','shield','primary')+'</div>';
 const salesGap=d.salesCutoff===null?null:d.salesActual-d.salesProjected,workGap=d.workCutoff===null?null:d.workActual-d.workProjected;
 const salesStatus=d.salesCutoff===null?'Sem dados':(salesGap>=0?'Acima do plano':'Abaixo do plano'),workStatus=d.workCutoff===null?'Sem dados':(workGap>=0?'Adiantada':'Atrasada');
 const tableRows=Array.from({length:maxEdit+1},(_,t)=>{const pr=d.planR.rows[Math.min(t,d.planR.rows.length-1)]||{},projW=t>=d.planParams.workStart&&t<=d.planR.totals.workEnd?(d.planR.workWeights[t-d.planParams.workStart]||0)*100:0,s=Object.prototype.hasOwnProperty.call(d.a.sales,t)?d.a.sales[t]:'',w=Object.prototype.hasOwnProperty.call(d.a.work,t)?d.a.work[t]:'';return '<tr><td>M'+t+' · '+planDate(d.planParams,t)+'</td><td>'+fmt(pr.units||0)+'</td><td><input class="actual-input" data-actual-sales="'+t+'" type="number" min="0" step="1" inputmode="numeric" value="'+s+'" placeholder="—" aria-label="Vendas realizadas no mês '+t+'"></td><td>'+pct(projW,2)+'</td><td><input class="actual-input" data-actual-work="'+t+'" type="number" min="0" max="100" step="0.01" inputmode="decimal" value="'+w+'" placeholder="—" aria-label="Avanço físico realizado no mês '+t+'"></td></tr>';}).join('');
 return heading('Projetado × realizado.','O cenário aprovado deixa de ser uma hipótese quando encontra a execução real.',btn('export','Backup do estudo','download'))+baseline+'<div class="kpis">'+
  kpi('Vendas acumuladas',d.salesCutoff===null?'—':fmt(d.salesActual)+' lotes',d.salesCutoff===null?'Informe o realizado mensal':salesStatus+' · plano '+fmt(d.salesProjected)+' até M'+d.salesCutoff,'wallet',d.salesCutoff!==null&&salesGap<0)+
  kpi('Velocidade real de vendas',d.salesCutoff===null?'—':fmt(d.salesActualSpeed,2)+' lotes/mês',d.salesCutoff===null?'Sem histórico': 'Plano no mesmo período: '+fmt(d.salesProjSpeed,2)+' lotes/mês','chart')+
  kpi('Avanço físico realizado',d.workCutoff===null?'—':pct(d.workActual,1),d.workCutoff===null?'Informe o avanço mensal':workStatus+' · plano '+pct(d.workProjected,1)+' até M'+d.workCutoff,'work',d.workCutoff!==null&&workGap<0)+
  kpi('Velocidade real da obra',d.workCutoff===null?'—':pct(d.workActualSpeed,2)+' / mês',d.workCutoff===null?'Sem histórico':'Plano no mesmo período: '+pct(d.workProjSpeed,2)+' / mês','layers')+'</div>'+
 '<div class="grid-two">'+section('Velocidade de vendas','Lotes vendidos acumulados: projetado versus realizado.',paceChart(salesRows,'projSalesCum','actualSalesCum',{title:'Vendas acumuladas',unit:'number',max:d.planR.totals.qty})+'<div class="comparison-summary"><span>Desvio no corte'+(d.salesCutoff===null?'<b>—</b>':'<b>'+deltaBadge(salesGap,' lotes')+'</b>')+'</span><span>Sell-out projetado<b>M'+d.planR.totals.lastSale+'</b></span><span>Sell-out pelo ritmo realizado<b>'+(d.selloutForecast===null?'—':'M'+d.selloutForecast)+'</b></span></div>')+
 section('Velocidade física da obra','Percentual físico acumulado: curva projetada versus avanço realizado.',paceChart(workRows,'projWorkCum','actualWorkCum',{title:'Avanço físico acumulado',unit:'percent',max:100})+'<div class="comparison-summary"><span>Desvio no corte'+(d.workCutoff===null?'<b>—</b>':'<b>'+deltaBadge(workGap,' p.p.')+'</b>')+'</span><span>Entrega projetada<b>M'+d.planR.totals.workEnd+'</b></span><span>Entrega pelo ritmo realizado<b>'+(d.workForecast===null?'—':'M'+d.workForecast)+'</b></span></div>')+'</div>'+
 section('Lançamento do realizado','Preencha apenas meses já encerrados. Campos vazios significam “sem informação”; zero informado significa realizado igual a zero.','<div class="table-actions"><label class="help-chip">Período visível</label><select class="inline-select" data-control="actualRange">'+[[24,'Até M24'],[36,'Até M36'],[60,'Até M60'],['all','Ciclo relevante']].map(([v,l])=>'<option value="'+v+'" '+(String(actualRange)===String(v)?'selected':'')+'>'+l+'</option>').join('')+'</select><span class="help-chip">Vendas em lotes · obra em pontos percentuais do mês</span></div><div class="table-wrap actuals-table"><table><thead><tr><th>Mês</th><th>Vendas projetadas</th><th>Vendas realizadas</th><th>Avanço físico projetado</th><th>Avanço físico realizado</th></tr></thead><tbody>'+tableRows+'</tbody></table></div><p class="table-caption">O realizado pertence a este empreendimento. A obra realizada é lançada como avanço físico mensal; a soma é limitada a 100%. As projeções financeiras não são substituídas automaticamente pelos realizados: este módulo compara execução e plano sem reescrever a viabilidade original.</p>')+
 '<div class="portfolio-note">'+ico('help')+'<p><b>Leitura recomendada:</b> velocidade de venda abaixo do plano aumenta o risco de funding; obra acima do plano pode antecipar desembolsos. A combinação crítica é obra adiantada com vendas atrasadas. O baseline congelado evita que uma revisão de premissas apague o desvio histórico.</p></div>';
}

